"use client";

import type { CSSProperties, ReactNode } from "react";

export type BlurInState = "hidden" | "revealed";

export type BlurInDirection = "up" | "down" | "left" | "right";

export interface BlurInStyle {
  blur: number;
  opacity: number;
  translateX: number;
  translateY: number;
}

export interface BlurInStyleContext {
  blur: number;
  distance: number;
  axis: "x" | "y";
  sign: 1 | -1;
}

export const blurInStyleContext = (
  blur: number,
  direction: BlurInDirection,
  distance: number
): BlurInStyleContext => {
  const axis: "x" | "y" =
    direction === "left" || direction === "right" ? "x" : "y";
  const sign: 1 | -1 = direction === "up" || direction === "left" ? 1 : -1;
  return { axis, blur, distance, sign };
};

export const blurInStyle = (
  state: BlurInState,
  ctx: BlurInStyleContext
): BlurInStyle => {
  if (state === "revealed") {
    return { blur: 0, opacity: 1, translateX: 0, translateY: 0 };
  }
  return {
    blur: ctx.blur,
    opacity: 0,
    translateX: ctx.axis === "x" ? ctx.sign * ctx.distance : 0,
    translateY: ctx.axis === "y" ? ctx.sign * ctx.distance : 0,
  };
};

export interface BlurInProps {
  state?: BlurInState;
  style?: BlurInStyle;
  children: ReactNode;
  blur?: number;
  direction?: BlurInDirection;
  distance?: number;
  display?: CSSProperties["display"];
  className?: string;
}

export const BlurIn = ({
  state = "hidden",
  style,
  children,
  blur = 8,
  direction = "up",
  distance = 12,
  display = "inline-block",
  className,
}: BlurInProps) => {
  const v =
    style ?? blurInStyle(state, blurInStyleContext(blur, direction, distance));
  return (
    <div
      className={className}
      style={{
        display,
        filter: v.blur > 0 ? `blur(${v.blur}px)` : "none",
        opacity: v.opacity,
        transform: `translate(${v.translateX}px, ${v.translateY}px)`,
      }}
    >
      {children}
    </div>
  );
};

"use client";

import { easings, useStateTransition } from "@/lib/framecn-ui";
import type { Step } from "@/lib/framecn-ui";
import {
  blurInStyle,
  blurInStyleContext,
} from "@/components/framecn/blur-in";
import type {
  BlurInDirection,
  BlurInState,
  BlurInStyle,
} from "@/components/framecn/blur-in";

export const DEFAULT_DURATION = 18;

export const tweenBlurInStyle = (
  a: BlurInStyle,
  b: BlurInStyle,
  t: number
): BlurInStyle => ({
  blur: a.blur + (b.blur - a.blur) * t,
  opacity: a.opacity + (b.opacity - a.opacity) * t,
  translateX: a.translateX + (b.translateX - a.translateX) * t,
  translateY: a.translateY + (b.translateY - a.translateY) * t,
});

export interface BlurInTransitionOptions {
  blur?: number;
  direction?: BlurInDirection;
  distance?: number;
  speed?: number;
  defaultDuration?: number;
}

export const useBlurInTransition = (
  steps: Step<BlurInState>[],
  opts: BlurInTransitionOptions = {}
): BlurInStyle => {
  const {
    blur = 8,
    direction = "up",
    distance = 12,
    speed = 1,
    defaultDuration = DEFAULT_DURATION,
  } = opts;
  const ctx = blurInStyleContext(blur, direction, distance);
  const { from, to, progress } = useStateTransition(
    steps,
    "hidden",
    speed,
    defaultDuration
  );
  const t = easings.out(progress);
  return tweenBlurInStyle(blurInStyle(from, ctx), blurInStyle(to, ctx), t);
};
